import{_ as s,C as l,c as r,o as u,ag as i,j as t,G as a,a as n}from"./chunks/framework.Bw-5EFTY.js";const w=JSON.parse('{"title":"Easy Digital Downloads Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/easy-digital-downloads-integration-with-fluentaffiliate.md","filePath":"guide/integrations/easy-digital-downloads-integration-with-fluentaffiliate.md","lastUpdated":1755766981000}'),d={name:"guide/integrations/easy-digital-downloads-integration-with-fluentaffiliate.md"};function g(f,e,c,p,h,m){const o=l("ZoomableImage");return u(),r("div",null,[e[0]||(e[0]=i('<h1 id="easy-digital-downloads-integration-with-fluentaffiliate" tabindex="-1">Easy Digital Downloads Integration with FluentAffiliate <a class="header-anchor" href="#easy-digital-downloads-integration-with-fluentaffiliate" aria-label="Permalink to &quot;Easy Digital Downloads Integration with FluentAffiliate&quot;">​</a></h1><p>Easy Digital Downloads (EDD) is a e-commerce plugin for WordPress, specifically designed to make selling digital products simple and efficient. By pairing EDD with FluentAffiliate, you can create a powerful affiliate program to promote your digital downloads, like eBooks &amp; softwares, and manage your affiliate commissions effortlessly.</p><p>This guide will walk you through how to connect Easy Digital Downloads with FluentAffiliate step by step.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Easy Digital Downloads is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>Before you begin, please ensure that both the Easy Digital Downloads and FluentAffiliate plugins are installed and activated on your WordPress site.</p></div><h2 id="enable-the-edd-integration" tabindex="-1">Enable the EDD Integration <a class="header-anchor" href="#enable-the-edd-integration" aria-label="Permalink to &quot;Enable the EDD Integration&quot;">​</a></h2><p>The first step is to activate the EDD module within your FluentAffiliate settings. Once Easy Digital Download is running on your site, you can connect it to <strong>FluentAffiliate</strong>.</p><ol><li>Go to your <strong>FluentAffiliate Dashboard</strong> and click on the Settings tab in the top menu.</li><li>From the menu on the left, select <strong>Integration Settings</strong>.</li><li>You will see a list of available integrations. Find <strong>Easy Digital Downloads</strong> and click the <strong>toggle</strong> button next to it to turn it on.</li></ol><p>Your <strong>Easy Digital Downloads</strong> integration is now active, allowing affiliates to earn referral commissions on your digital sales.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how affiliate commissions work with your products.</p>',9)),t("p",null,[a(o,{src:"/guide/public/images/integrations/edd/integration-setup-options.webp",alt:"Integration Settings"})]),e[1]||(e[1]=t("h2",{id:"configure-edd-settings",tabindex:"-1"},[n("Configure EDD Settings "),t("a",{class:"header-anchor",href:"#configure-edd-settings","aria-label":'Permalink to "Configure EDD Settings"'},"​")],-1)),e[2]||(e[2]=t("p",null,"In the management panel, you can customize exactly how your affiliate program will work with EDD. Here are the options you can configure:",-1)),e[3]||(e[3]=t("ul",null,[t("li",null,[t("strong",null,"Enable Branded Coupon Codes for affiliates:"),n(" When you enable this feature, you can offer branded coupon codes to your affiliates. This allows them to promote products with unique discount codes, giving them another powerful marketing opportunity.")])],-1)),t("p",null,[a(o,{src:"/guide/public/images/integrations/edd/branded-coupon-code.webp",alt:"Branded Coupon Code"})]),e[4]||(e[4]=i('<p>For example, this is perfect if you want to give a special coupon code to a social media influencer who is also one of your affiliates.To assign a coupon to a specific affiliate, follow these steps:</p><ol><li><p>From your WordPress dashboard, navigate to <strong>Downloads</strong> &gt; <strong>Discounts</strong>.</p></li><li><p>You can either create a new discount or edit an existing one.</p></li><li><p>On the discount editor page, scroll down to find the <strong>FluentAffiliate Coupon</strong> section.</p></li><li><p>Click on the dropdown field and select the <strong>affiliate&#39;s</strong> name from the list.</p></li><li><p><strong>Save</strong> the discount. Now, when this discount code is used for a purchase, the selected affiliate will automatically be credited with the referral.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Before you can assign a coupon, the user must already be an approved affiliate in your FluentAffiliate program.</p></div>',3)),t("p",null,[a(o,{src:"/guide/public/images/integrations/edd/fluentaffilaie-coupon.webp",alt:"Branded Coupon Code"})]),e[5]||(e[5]=i('<ul><li><p><strong>Disable Referrals on Upgrades:</strong> If you sell products with multiple tiers or upgrades, you can check this box to prevent commissions from being generated on upgrade purchases. This ensures affiliates are only rewarded for the initial sale.</p></li><li><p><strong>Enable custom rate for specific product or categories:</strong> Check this box to set special commission rates for certain digital products or categories, which will override your global default rate.</p></li></ul><p>After that, click on the <strong>+Add New Group</strong> button. You will find options to choose how you want to apply this custom rate. You can set it for specific individual products or for entire product categories.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This feature gives you the flexibility to offer different commission rates for different products. For example, you could offer a higher commission on a new product as an incentive for affiliates to promote it more heavily.</p></div><ul><li><p><strong>Select Products:</strong> In the Select field, begin typing the name of the digital product you want to set a custom rate for and choose it from the list.</p></li><li><p><strong>Select Rate:</strong> Enter the new commission value (e.g., 25 for 25% or $25). Next, use the dropdown menu to choose if the rate is a Percentage (%) of the sale or a Fixed dollar amount.</p></li><li><p><strong>Save Settings:</strong> Once you have configured all your custom rates, click the <strong>Save Settings</strong> button to make them live.</p></li></ul><p>You can select multiple custom rate types for products or categories by clicking the <strong>+ Add New Group</strong> button.</p><p>Also, you can delete the affiliate rates by clicking the <em>delete</em> icon in the top right corner.</p>',6)),t("p",null,[a(o,{src:"/guide/public/images/integrations/edd/custom-affiliate-rates.gif",alt:"EDD Settings"})]),e[6]||(e[6]=i('<h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>Once you&#39;ve finished setting up your <strong>Easy Digital Downloads</strong> product settings, it&#39;s time to generate your <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a>.</p><h3 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h3><p>Here are solutions to common issues you might encounter:</p><ul><li><strong>Commissions Not Tracking:</strong> Verify that the integration toggle is enabled. Also, you can test your affiliate link to ensure it working.</li><li><strong>Product Page Not Tracking:</strong> Make sure the product page URL is correctly set up in the affiliate link generator.</li></ul><p>And that&#39;s it. This is an easy process to integrate Easy Digital Downloads with FluentAffiliate.</p>',6))])}const b=s(d,[["render",g]]);export{w as __pageData,b as default};
